def transform(grid):
 g=[row[:] for row in grid]; h=len(g); w=len(g[0])
 bg=max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid)); col=next(v for v in set(v for row in grid for v in row) if v!=bg)
 for r in range(h):
  xs=[c for c in range(w) if grid[r][c]==col]
  for a,b in zip(xs,xs[1:]):
   if b-a<=4:
    for c in range(a+1,b):
     if g[r][c]==bg:g[r][c]=2
 for c in range(w):
  ys=[r for r in range(h) if grid[r][c]==col]
  for a,b in zip(ys,ys[1:]):
   if b-a<=4:
    for r in range(a+1,b):
     if g[r][c]==bg:g[r][c]=2
 return g

